// Normalise et valide l'entrée (évite toute donnée bizarre vers la base)
const body = $input.first().json.body || {};
const key = String(body.key || '').trim().toUpperCase();
const machineId = String(body.machineId || '').trim().toLowerCase();
const appVersion = String(body.appVersion || '').trim();

const valid = /^[A-Z0-9-]{4,64}$/.test(key)
  && /^[a-f0-9]{64}$/.test(machineId)
  && /^[\w.\-]{0,20}$/.test(appVersion);

return [{ json: { valid, key: valid ? key : 'INVALIDE', machineId: valid ? machineId : '0', appVersion } }];

// Décide si l'activation est autorisée
const input = $('Valider entrée').first().json;
const row = $input.first().json || {};

const refus = (code, message) => [{ json: { ok: false, code, message } }];

if (!input.valid) return refus(400, 'Requête invalide');
if (!row.key) return refus(404, 'Clé de licence inconnue');
if (row.revoked) return refus(403, 'Licence révoquée');
if (row.expires_at && new Date(row.expires_at) < new Date()) return refus(403, 'Licence expirée');
if (!row.deja_active && Number(row.nb_activations) >= Number(row.max_machines)) {
  return refus(403, `Nombre maximum de Mac atteint (${row.max_machines}). Désactivez un autre Mac.`);
}

return [{ json: {
  ok: true,
  key: row.key,
  machineId: input.machineId,
  appVersion: input.appVersion,
  plan: row.plan,
  expiresAt: row.expires_at ? Math.floor(new Date(row.expires_at).getTime() / 1000) : null,
} }];

// Signe la licence avec la clé privée Ed25519
// Prérequis n8n : NODE_FUNCTION_ALLOW_BUILTIN=crypto et la variable HANA_LICENCE_PRIVATE_KEY
const crypto = require('crypto');
const d = $('Décider').first().json;

const now = Math.floor(Date.now() / 1000);
const JOURS_HORS_LIGNE = 30; // durée pendant laquelle l'app fonctionne sans revalider
let validUntil = now + JOURS_HORS_LIGNE * 86400;
if (d.expiresAt) validUntil = Math.min(validUntil, d.expiresAt);

const payload = {
  key: d.key,
  machineId: d.machineId,
  plan: d.plan,
  expiresAt: d.expiresAt,
  issuedAt: now,
  validUntil,
};

const pem = $env.HANA_LICENCE_PRIVATE_KEY.replace(/\\n/g, '\n');
const payloadBuf = Buffer.from(JSON.stringify(payload), 'utf8');
const signature = crypto.sign(null, payloadBuf, crypto.createPrivateKey(pem));

return [{ json: {
  payload: payloadBuf.toString('base64'),   // signé tel quel : ne jamais le reformater
  signature: signature.toString('base64'),
} }];

